public static Node<Integer> reverse(Node<Integer> first) {
    Node<Integer> prev = null;
    Node<Integer> p = first;
    while (p != null) {
        Node<Integer> next = p.getNext();
        p.setNext(prev);
        prev = p;
        p = next;
    }
    return prev;
}

public static int middle(Node<Integer> first) {
    Node<Integer> slow = first;
    Node<Integer> fast = first;
    while (fast != null && fast.getNext() != null) {
        slow = slow.getNext();
        fast = fast.getNext().getNext();
    }
    return slow.getValue();
}

