public static Node<int> Reverse(Node<int> first)
{
    Node<int> prev = null;
    Node<int> p = first;
    while (p != null)
    {
        Node<int> next = p.GetNext();
        p.SetNext(prev);
        prev = p;
        p = next;
    }
    return prev;
}

public static int Middle(Node<int> first)
{
    Node<int> slow = first;
    Node<int> fast = first;
    while (fast != null && fast.GetNext() != null)
    {
        slow = slow.GetNext();
        fast = fast.GetNext().GetNext();
    }
    return slow.GetValue();
}

